// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 超管读取子账号列表
	// (GET /v1/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// 超管创建子账号并标记强改
	// (POST /v1/accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// 超管重置子账号初始口令
	// (POST /v1/accounts/{accountId}/password:reset)
	ResetAccountPassword(ctx context.Context, request ResetAccountPasswordRequestObject) (ResetAccountPasswordResponseObject, error)
	// 修改10项功能权限
	// (PUT /v1/accounts/{accountId}/permissions)
	SetAccountPermissions(ctx context.Context, request SetAccountPermissionsRequestObject) (SetAccountPermissionsResponseObject, error)
	// 停用/恢复/删除子账号
	// (PUT /v1/accounts/{accountId}/status)
	SetAccountStatus(ctx context.Context, request SetAccountStatusRequestObject) (SetAccountStatusResponseObject, error)
	// 按最新账号功能权限授权
	// (POST /v1/authorizations/check)
	CheckAuthorization(ctx context.Context, request CheckAuthorizationRequestObject) (CheckAuthorizationResponseObject, error)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// portal内部核对CSRF
	// (POST /v1/csrf:verify)
	VerifySessionCSRF(ctx context.Context, request VerifySessionCSRFRequestObject) (VerifySessionCSRFResponseObject, error)
	// 读自身后台偏好
	// (GET /v1/preferences)
	ReadPreferences(ctx context.Context, request ReadPreferencesRequestObject) (ReadPreferencesResponseObject, error)
	// 保存自身主题/语言/默认后台页
	// (PUT /v1/preferences)
	UpdatePreferences(ctx context.Context, request UpdatePreferencesRequestObject) (UpdatePreferencesResponseObject, error)
	// 决定后台显示首次注册或登录
	// (GET /v1/registration)
	ReadRegistrationState(ctx context.Context, request ReadRegistrationStateRequestObject) (ReadRegistrationStateResponseObject, error)
	// 首个注册账户原子成为唯一超管
	// (POST /v1/registration)
	RegisterFirstSuperadmin(ctx context.Context, request RegisterFirstSuperadminRequestObject) (RegisterFirstSuperadminResponseObject, error)
	// 读取当前账户
	// (GET /v1/self)
	ReadSelf(ctx context.Context, request ReadSelfRequestObject) (ReadSelfResponseObject, error)
	// 改口令并结束其他设备登录
	// (POST /v1/self/password:change)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// 读取自身登录设备
	// (GET /v1/sessions)
	ReadSessions(ctx context.Context, request ReadSessionsRequestObject) (ReadSessionsResponseObject, error)
	// 账号名口令登录
	// (POST /v1/sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
	// 退出当前或指定自身登录
	// (DELETE /v1/sessions/{sessionId})
	RevokeSession(ctx context.Context, request RevokeSessionRequestObject) (RevokeSessionResponseObject, error)
	// 内部透明轮换session
	// (POST /v1/sessions:refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

